var WEBSITE = "https://v2.shlib.life";

function memoizeAsync(load, keyOf = (...args) => JSON.stringify(args)) {
  const pending = new Map();
  return (...args) => {
    const key = keyOf(...args);
    let hit = pending.get(key);
    if (!hit) {
      hit = load(...args).catch(() => null).then((value) => {
        if (value === null) pending.delete(key);
        return value;
      });
      pending.set(key, hit);
    }
    return hit;
  };
}

async function fetchResponse(url, options) {
  try {
    const res = options ? await fetch(url, options) : await fetch(url);
    return res.ok ? res : null;
  } catch {
    return null;
  }
}
async function fetchJson(url, options) {
  try {
    const res = await fetchResponse(url, options);
    return res ? res.json() : null;
  } catch {
    return null;
  }
}

var PARTS_RE = /^([^?#]*)(?:\?([^#]*))?(#.*)?$/;
function withQuery(url, params) {
  const [, base = "", query = "", hash = ""] = PARTS_RE.exec(url) ?? [];
  const search = new URLSearchParams(query);
  for (const [name, value] of Object.entries(params)) search.set(name, value);
  return `${base}?${search.toString()}${hash}`;
}

function chapterOrderValue(chapter) {
  const value = parseFloat(chapter);
  return Number.isNaN(value) ? Number.POSITIVE_INFINITY : value;
}
